CREATE VIEW v72963 AS SELECT *, (RELEASE_LOCK('test1') = 1) AND (RELEASE_LOCK('test3') IS NULL) AND (RELEASE_LOCK('test2') = 1) AS x1, ST_ASTEXT(ST_CENTROID(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(LINESTRING(0 0,0 10,10 10,10 0),LINESTRING(0 0,10 0,10 -10,0 -10))'))) AS x2 FROM v72804 AS x5, v72884 AS x6 WHERE x6.v72887 >= 6 OR x5.v72805 <> x6.v72887